import assert from "node:assert/strict";
import { runInNewContext } from "node:vm";
import { after, before, describe, it } from "node:test";
import { startServer, type Running } from "./helpers/server.ts";

interface Task {
  id: number;
  title: string;
}

interface ApiError {
  error: { code: string; message: string };
}

function post(server: Running, title: unknown): Promise<Response> {
  return fetch(`${server.baseUrl}/api/tasks`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ title }),
  });
}

async function listTasks(server: Running): Promise<Task[]> {
  const body = (await (await fetch(`${server.baseUrl}/api/tasks`)).json()) as { tasks: Task[] };
  return body.tasks;
}

async function assertRejected(server: Running, title: unknown, message: string) {
  const before = await listTasks(server);
  const response = await post(server, title);
  assert.equal(response.status, 400);
  const body = (await response.json()) as ApiError;
  assert.equal(body.error.code, "validation_failed");
  assert.equal(body.error.message, message);
  assert.deepEqual(await listTasks(server), before, "nothing was stored");
}

const REQUIRED = "A title is required.";
const TOO_LONG = "The title is too long (maximum 500 characters).";

describe("SL-004 reject empty and over-long titles", () => {
  describe("AC-1: a title that is empty after trimming", () => {
    let server: Running;
    before(async () => {
      server = await startServer();
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-1: an empty title answers 400 validation_failed and stores nothing", async () => {
      await assertRejected(server, "", REQUIRED);
    });

    it("AC-1: a title of only spaces, tabs and newlines is rejected the same way", async () => {
      await assertRejected(server, "   \t\n  ", REQUIRED);
    });

    it("AC-1: a title that is not a string is rejected, not a 500", async () => {
      await assertRejected(server, 42, "Title must be a string.");
      await assertRejected(server, null, "Title must be a string.");
    });

    it("AC-1: a missing title is rejected, not a 500", async () => {
      const response = await fetch(`${server.baseUrl}/api/tasks`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({}),
      });
      assert.equal(response.status, 400);
      const body = (await response.json()) as ApiError;
      assert.equal(body.error.code, "validation_failed");
      assert.deepEqual(await listTasks(server), []);
    });
  });

  describe("AC-2: a title longer than 500 characters", () => {
    let server: Running;
    before(async () => {
      server = await startServer();
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-2: 501 characters answers 400 validation_failed and stores nothing", async () => {
      await assertRejected(server, "a".repeat(501), TOO_LONG);
    });

    it("AC-2: exactly 500 characters is accepted", async () => {
      const response = await post(server, "a".repeat(500));
      assert.equal(response.status, 201);
      const { task } = (await response.json()) as { task: Task };
      assert.equal(task.title.length, 500);
    });

    it("AC-2: the limit counts the trimmed title, so 500 characters plus spaces is accepted", async () => {
      const response = await post(server, `  ${"b".repeat(500)}  `);
      assert.equal(response.status, 201);
    });

    it("AC-2: 501 characters plus spaces is still rejected", async () => {
      await assertRejected(server, ` ${"c".repeat(501)} `, TOO_LONG);
    });

    it("AC-2: characters are counted as characters, not UTF-16 units", async () => {
      assert.equal((await post(server, "😀".repeat(500))).status, 201);
      await assertRejected(server, "😀".repeat(501), TOO_LONG);
    });
  });

  describe("AC-1 and AC-2: the page shows the reason", () => {
    let server: Running;
    let html: string;
    let script: string;
    before(async () => {
      server = await startServer();
      html = await (await fetch(`${server.baseUrl}/`)).text();
      script = await (await fetch(`${server.baseUrl}/app.js`)).text();
    });
    after(async () => {
      await server?.stop();
    });

    it("has an alert element with id form-message", () => {
      assert.match(html, /<[a-z]+(?=[^>]*id=["']form-message["'])(?=[^>]*role=["']alert["'])/);
    });

    /** Runs the real page script against the real server, with a minimal fake DOM. */
    async function submit(title: string) {
      const elements: Record<string, any> = {
        "task-form": { handlers: {} as Record<string, Function>, addEventListener(t: string, f: Function) { this.handlers[t] = f; } },
        "task-title": { value: title },
        "task-list": { children: [] as unknown[], replaceChildren(...c: unknown[]) { this.children = c; } },
        "form-message": { textContent: "" },
      };
      const pending: Promise<unknown>[] = [];
      const context = {
        document: {
          getElementById: (id: string) => elements[id],
          createElement: () => ({ textContent: "" }),
        },
        fetch: (url: string, init?: RequestInit) => {
          const request = fetch(`${server.baseUrl}${url}`, init);
          pending.push(request);
          return request;
        },
      };
      runInNewContext(script, context);
      await new Promise((resolve) => setTimeout(resolve, 100));
      await elements["task-form"].handlers.submit({ preventDefault() {} });
      await new Promise((resolve) => setTimeout(resolve, 100));
      return elements;
    }

    it("AC-1: an empty title shows the server's message and keeps what was typed", async () => {
      const page = await submit("   ");
      assert.equal(page["form-message"].textContent, REQUIRED);
      assert.equal(page["task-title"].value, "   ");
    });

    it("AC-2: an over-long title shows the server's message and keeps what was typed", async () => {
      const page = await submit("x".repeat(501));
      assert.equal(page["form-message"].textContent, TOO_LONG);
      assert.equal(page["task-title"].value, "x".repeat(501));
      assert.deepEqual(await listTasks(server), []);
    });

    it("a valid title clears the field and any earlier message", async () => {
      const page = await submit("Buy milk");
      assert.equal(page["form-message"].textContent, "");
      assert.equal(page["task-title"].value, "");
      assert.equal(page["task-list"].children.length, 1);
    });
  });
});
EOF
